input.content:
// Delivers webhook events to billing-provider.
//
// This function performs exactly ONE HTTP attempt. Do not add a retry
// loop here: billing-provider has no idempotency key on this endpoint,
// so in-process retries were processed as separate charges (1,842
// customers double-charged during the 2023-11-14 outage; see the revert
// of "Add exponential backoff retries to the webhook dispatcher").
//
// Reliability comes from the delivery queue, which retries and
// deduplicates by event id. To let the queue do that, a delivery that
// does not succeed must be surfaced as a failure instead of being
// returned as if it were delivered: a 502 response returned normally
// used to be treated as "delivered", silently dropping the event.
async function deliver(io, event) {
  const res = await io.post('/webhooks/billing', event);
  if (res.status >= 200 && res.status < 300) {
    return res;
  }
  const err = new Error(`billing webhook delivery failed with status ${res.status}`);
  err.status = res.status;
  if (event && event.id) {
    err.eventId = event.id;
  }
  throw err;
}

module.exports = { deliver };

