node -e "
const { deliver } = require('/workspace/src/dispatcher.js');

(async () => {
  // 1. 2xx -> resolved with the response, exactly one attempt
  let calls = 0;
  const ok = await deliver({ post: async () => { calls++; return { status: 200, body: 'ok' }; } }, { id: 'evt-1' });
  console.log('2xx:', JSON.stringify(ok), 'calls =', calls);

  // 2. 502 -> rejected with status attached, exactly one attempt (no in-process retry)
  calls = 0;
  try {
    await deliver({ post: async () => { calls++; return { status: 502, body: 'bad gateway' }; } }, { id: 'evt-2' });
    console.log('502: UNEXPECTED RESOLVE');
  } catch (e) {
    console.log('502 rejected:', e.message, '| status =', e.status, '| eventId =', e.eventId, '| calls =', calls);
  }

  // 3. 404 (4xx) also surfaced as failure
  try {
    await deliver({ post: async () => ({ status: 404 }) }, { id: 'evt-3' });
    console.log('404: UNEXPECTED RESOLVE');
  } catch (e) {
    console.log('404 rejected:', e.message, '| status =', e.status);
  }
})();
"

